'AC18.4.2'; from datetime import UTC, date, datetime, timedelta; from unittest.mock import AsyncMock, patch; from uuid import uuid4; from fastapi import status; from httpx import AsyncClient; from src.extraction import RuleType; from src.extraction.orm.layer3 import ClassificationRule; from src.identity import User; from src.ledger import Account, AccountType; from src.reporting import ReportSnapshot, ReportType
class TestReportsEndpoints:
    async def test_get_available_currencies_success(self, client: AsyncClient, db): 'AC5.4.1'; response = await client.get('/reports/currencies'); assert response.status_code == status.HTTP_200_OK; currencies = response.json(); assert isinstance(currencies, list); assert len(currencies) > 0
    async def test_balance_sheet_success(self, client: AsyncClient, db, test_user: User): 'AC5.1.1'; today = date.today(); response = await client.get(f'/reports/balance-sheet?as_of_date={today}'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert isinstance(data, dict); assert 'assets' in data; assert 'liabilities' in data; assert 'equity' in data; assert 'total_assets' in data; assert 'total_liabilities' in data; assert 'total_equity' in data; assert 'equation_delta' in data; assert 'is_balanced' in data; assert 'currency' in data; assert 'as_of_date' in data
    async def test_balance_sheet_with_currency(self, client: AsyncClient, db, test_user: User): 'AC5.1.2'; today = date.today(); currency = 'USD'; response = await client.get(f'/reports/balance-sheet?as_of_date={today}&currency={currency}'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert data['currency'] == currency
    async def test_income_statement_success(self, client: AsyncClient, db, test_user: User): 'AC5.2.1'; start_date = date.today() - timedelta(days=30); end_date = date.today(); response = await client.get(f'/reports/income-statement?start_date={start_date}&end_date={end_date}'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert isinstance(data, dict); assert 'income' in data; assert 'expenses' in data; assert 'total_income' in data; assert 'total_expenses' in data; assert 'net_income' in data; assert 'currency' in data; assert 'start_date' in data; assert 'end_date' in data
    async def test_income_statement_with_filters(self, client: AsyncClient, db, test_user: User): 'AC5.2.2'; start_date = date.today() - timedelta(days=30); end_date = date.today(); tags = ['food', 'transport']; account_type = 'INCOME'; response = await client.get(f"/reports/income-statement?start_date={start_date}&end_date={end_date}&tags={','.join(tags)}&account_type={account_type}"); assert response.status_code == status.HTTP_200_OK
