    async def test_unauthenticated_access(self, public_client: AsyncClient, test_user: User): 'AC-reporting.errors.3 AC5.5.3'; response = await public_client.get('/reports/balance-sheet'); assert response.status_code == status.HTTP_401_UNAUTHORIZED
    async def test_account_lineage_unknown_account_returns_404(self, client: AsyncClient, db, test_user: User): response = await client.get(f'/reports/account-lineage?account_id={uuid4()}'); assert response.status_code == status.HTTP_404_NOT_FOUND
    async def test_account_lineage_returns_payload_for_known_account(self, client: AsyncClient, db, test_user: User): account = Account(user_id=test_user.id, name='Lineage Cash', type=AccountType.ASSET, currency='SGD'); db.add(account); await db.commit(); await db.refresh(account); response = await client.get(f'/reports/account-lineage?account_id={account.id}&currency=SGD'); assert response.status_code == status.HTTP_200_OK; body = response.json(); assert body['account_id'] == str(account.id); assert body['account_name'] == 'Lineage Cash'; assert body['currency'] == 'SGD'; assert isinstance(body['lines'], list); assert 'total' in body
    async def test_export_cash_flow_missing_dates_returns_400(self, client: AsyncClient, db, test_user: User): response = await client.get('/reports/export?report_type=cash-flow&format=csv'); assert response.status_code == status.HTTP_400_BAD_REQUEST
    async def test_generate_personal_report_package_snapshot(self, client: AsyncClient, db, test_user: User): today = date.today(); start = today - timedelta(days=30); response = await client.post('/reports/package/generate', json={'start_date': start.isoformat(), 'end_date': today.isoformat(), 'as_of_date': today.isoformat(), 'currency': 'SGD'}); assert response.status_code == status.HTTP_200_OK; body = response.json(); assert body['id']; assert body['currency'] == 'SGD'; assert body['status']; document = body['document']; assert document['lifecycle'] == 'frozen'; section_payloads = document['sections']; assert all((section in section_payloads for section in ('balance_sheet', 'income_statement', 'cash_flow')))
